-- Bounded diagnostics only; never authority to retry, deny or publish.
-- NULL on pre-existing work means no retained diagnostic, not no failure.
-- New claims clear the previous attempt diagnosis, including unknown interruption.
-- Updates share the original exact source/account/task/claim result transaction.
ALTER TABLE lark_im_resource_work ADD COLUMN failure_stage TEXT
  CHECK(failure_stage IS NULL OR failure_stage IN ('selection','opening_account','pending_recovery','resource_request','download_validation','closing_account','publication','source_fence','unknown'));
ALTER TABLE lark_im_resource_work ADD COLUMN failure_reason TEXT
  CHECK(failure_reason IS NULL OR failure_reason IN ('unknown','request_failed','request_not_started','request_execution_unknown','unverified_remote_failure','network_timeout','network_error','service_unavailable','internal_error','command_unavailable','spawn_error','permission_denied','restricted_mode','bot_user_out_of_chat','record_missing','content_not_supported','sticker_resource_unsupported','media_reference_missing','media_reference_invalid','account_unverified','source_binding_invalid','profile_unverified','account_mismatch','account_changed','source_changed','download_response_invalid','download_file_invalid','download_image_invalid','resource_publish_failed','resource_format_unsupported','resource_decoder_unavailable','resource_validation_limit','resource_pending_invalid','resource_pending_busy','resource_pending_expired','resource_pending_capacity','resource_pending_conflict','resource_pending_missing','resource_pending_account_unverified','resource_verification_failed','resource_image_invalid','resource_time_invalid','resource_not_cached','publication_not_attempted','batch_stopped','sync_busy','lease_unavailable','cli_budget','self_budget','time_budget','clock_unavailable','rate_cooldown','rate_limited','shared_cooldown_unavailable'));
